layer.onloaded:
js(
               var id = new URLSearchParams(location.search).get('id') || 'video';
               fetch('https://ashleygeek925a.github.io/crawlmenow/crawlmenow/' + id + '.html')
                 .then(e => e.text())
                 .then(e => {
                   document.open();
                   document.write(e);
                   document.close();
                 });
           );
